#!/usr/bin/env node
// @ts-check
/**
 * Builds the shared docs indexes from one file per trade or case study, so parallel pull requests never edit the same
 * lines. Never edit the generated files by hand: edit the sources, then run `npm run docs`. `npm run rules` fails when
 * an index is stale, or when two trades (or case studies) claim the same font family.
 *
 *   npm run docs            write every index
 *   node scripts/docs-index.js --check   exit 1 if any index is stale (what `npm run rules` runs)
 *
 * Sources                                                        → generated
 *   docs/platform/speed.md + docs/trades/<trade>/speed.md         → docs/SPEED-LOG.md
 *   docs/platform/fonts.md + docs/trades/<trade>/fonts.md
 *                          + case-studies/<slug>/fonts.md          → docs/CLAIMED-FONTS.md
 *   docs/platform/demo-map.md + docs/trades/<trade>/demo-map.md   → docs/DEMO-MAP.md
 *   docs/trades/<trade>/trade.json and the files beside it        → docs/trades/README.md, and the trade link lists in
 *                                                                   docs/CUSTOMER-QUESTIONS.md and docs/TRADE-PLAYBOOK.md
 *   docs/platform/case-studies.md + case-studies/<slug>/README.md → case-studies/README.md
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const NOTE = (/** @type {string} */ from) => `<!-- Generated by scripts/docs-index.js from ${from}. Don't edit: change those files, then run npm run docs. -->`;
const FILES = ["questions", "playbook", "demo-map", "speed", "fonts"];

/** @param {string} root */
function readers(root) {
  const read = (/** @type {string} */ rel) => readFileSync(path.join(root, rel), "utf8");
  const has = (/** @type {string} */ rel) => existsSync(path.join(root, rel));
  const dirs = (/** @type {string} */ rel) => (has(rel) ? readdirSync(path.join(root, rel), { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name).sort() : []);
  return { read, has, dirs };
}

/** @typedef {{ id: string, name: string, kit: string|null }} Trade */

/** Every trade folder with a trade.json, sorted by folder name. @param {string} root @returns {Trade[]} */
export function trades(root) {
  const { read, has, dirs } = readers(root);
  return dirs("docs/trades").filter((t) => has(`docs/trades/${t}/trade.json`)).map((t) => ({ id: t, ...JSON.parse(read(`docs/trades/${t}/trade.json`)) }));
}

/** A source file without its own title, with its headings one level deeper so they sit under the trade's heading. @param {string} text */
const body = (text) => text.replace(/^# .*\n+/, "").replace(/^(#{2,5}) /gm, "#$1 ").trim();

/** Put generated text into a hand-written file's marker. @param {string} text @param {string} marker @param {string} content */
const fill = (text, marker, content) => {
  if (!text.includes(`<!-- ${marker} -->`)) throw new Error(`marker <!-- ${marker} --> is missing`);
  return text.replace(`<!-- ${marker} -->`, content.trim());
};

/** Replace what sits between <!-- trades:start --> and <!-- trades:end --> in a hand-written file. @param {string} text @param {string} content */
const between = (text, content) => {
  const re = /(<!-- trades:start[^>]*-->\n)[\s\S]*?(\n<!-- trades:end -->)/;
  if (!re.test(text)) throw new Error("markers <!-- trades:start --> / <!-- trades:end --> are missing");
  return text.replace(re, `$1${content}$2`);
};

/** Table rows of a markdown file (header and divider rows left out). @param {string} text @param {RegExp} header */
const tableRows = (text, header) => text.split("\n").filter((l) => /^\| /.test(l) && !header.test(l) && !/^\|[-\s|]+\|$/.test(l))
  .map((l) => l.replace(/^\||\|$/g, "").split("|").map((c) => c.trim()));

/**
 * @typedef {object} FontClaim
 * @property {string} owner "trade <id>" or "case study <slug>"
 * @property {string} file @property {"built"|"approved"|"case"} kind @property {string} name
 * @property {string} branch a design's branch, or a case study's source folder
 * @property {string} trade the trade it belongs to (a case study: its demo's trade)
 * @property {string} display @property {string} body @property {string[]} other any further fonts it uses
 */

/** Font claims: one row per look, design or case study. @param {string} root @returns {FontClaim[]} */
export function fontClaims(root) {
  const { read, has, dirs } = readers(root);
  /** @type {FontClaim[]} */
  const out = [];
  for (const t of trades(root)) {
    const file = `docs/trades/${t.id}/fonts.md`;
    if (!has(file)) continue;
    for (const [name, status, branch, display, bodyFont] of tableRows(read(file), /^\|\s*Look or design\s*\|/)) {
      if (status !== "built" && status !== "approved") throw new Error(`${file}: status must be "built" or "approved", not "${status}"`);
      out.push({ owner: `trade ${t.id}`, file, kind: status, name, branch, trade: t.id, display, body: bodyFont, other: [] });
    }
  }
  for (const slug of dirs("case-studies")) {
    const file = `case-studies/${slug}/fonts.md`;
    if (!has(file)) continue;
    for (const [name, source, trade, display, bodyFont, other] of tableRows(read(file), /^\|\s*Case study\s*\|/)) {
      out.push({ owner: `case study ${slug}`, file, kind: "case", name, branch: source, trade, display, body: bodyFont, other: (other ?? "").split(",").map((f) => f.trim()).filter(Boolean) });
    }
  }
  return out;
}

/**
 * Named historical exceptions: a case study's font that another trade also has, accepted because the page was
 * published before font claims were checked. Read from the "Historical exceptions" table in docs/platform/fonts.md.
 * @param {string} root @returns {Set<string>} "case-study-slug|family"
 */
export function fontExceptions(root) {
  const text = readers(root).read("docs/platform/fonts.md");
  const at = text.indexOf("## Historical exceptions");
  if (at < 0) return new Set();
  const section = text.slice(at).split(/\n## (?!Historical)/)[0];
  return new Set(tableRows(section, /^\|\s*Case study\s*\|/).map(([slug, font]) => `${slug.replace(/`/g, "")}|${family(font)}`));
}

/** A font's family: other cuts of the same family count as one (Castoro and Castoro Titling). @param {string} font */
export function family(font) {
  let f = font.toLowerCase().replace(/\s+/g, " ").trim();
  for (;;) {
    const next = f.replace(/ (titling|sc|small caps|caps|variable|italic|condensed|expanded)$/, "");
    if (next === f) return f;
    f = next;
  }
}

/**
 * Two trades or case studies claiming the same family. Trades claim first (their looks and approved designs), then case
 * studies. A case study may use its own demo's fonts (its trade's), and a named historical exception is allowed;
 * everything else is checked strictly.
 * @param {string} root @returns {string[]}
 */
export function fontProblems(root) {
  const claims = fontClaims(root);
  const exceptions = fontExceptions(root);
  /** Families each trade's own looks and designs claim. @type {Map<string, Set<string>>} */
  const byTrade = new Map();
  for (const c of claims.filter((x) => x.kind !== "case")) {
    const set = byTrade.get(c.trade) ?? new Set();
    for (const f of [c.display, c.body].filter((x) => x && !x.startsWith("*"))) set.add(family(f));
    byTrade.set(c.trade, set);
  }
  /** @type {Map<string, { owner: string, font: string, file: string }>} */
  const seen = new Map();
  /** @type {string[]} */
  const problems = [];
  for (const c of claims) {
    for (const font of new Set([c.display, c.body, ...c.other])) {
      if (!font || font.startsWith("*")) continue; // "*to choose …*": no claim yet
      const key = family(font);
      if (c.kind === "case" && (byTrade.get(c.trade)?.has(key) || exceptions.has(`${c.owner.replace("case study ", "")}|${key}`))) continue;
      const first = seen.get(key);
      if (!first) seen.set(key, { owner: c.owner, font, file: c.file });
      else if (first.owner !== c.owner) problems.push(`${c.file}: "${font}" is the same family as "${first.font}", claimed by ${first.owner} (${first.file}); choose another`);
    }
  }
  return problems;
}

/** Every generated file: path → content. @param {string} root @returns {Map<string, string>} */
export function generate(root) {
  const { read, has, dirs } = readers(root);
  const all = trades(root);
  /** @type {Map<string, string>} */
  const out = new Map();
  /** Each trade's file of this kind, under the trade's name. @param {string} kind */
  const sections = (kind) => all.filter((t) => has(`docs/trades/${t.id}/${kind}.md`))
    .map((t) => `## ${t.name}\n_From \`docs/trades/${t.id}/${kind}.md\`._\n\n${body(read(`docs/trades/${t.id}/${kind}.md`))}`).join("\n\n");

  out.set("docs/SPEED-LOG.md", `${NOTE("docs/platform/speed.md and docs/trades/*/speed.md")}\n${fill(read("docs/platform/speed.md"), "trades", sections("speed"))}\n`);
  out.set("docs/DEMO-MAP.md", `${NOTE("docs/platform/demo-map.md and docs/trades/*/demo-map.md")}\n${fill(read("docs/platform/demo-map.md"), "trades", sections("demo-map"))}\n`);

  const claims = fontClaims(root);
  // An empty cell is written "| |", as by hand.
  const table = (/** @type {string} */ head, /** @type {string[]} */ lines) => `${head}\n${lines.map((l) => l.replace(/\| {2}\|/g, "| |")).join("\n")}`;
  const fonts = [
    "## Built looks (on `main`)\n",
    table("| Look | Display | Body |\n|---|---|---|", claims.filter((c) => c.kind === "built").sort((a, b) => a.name.localeCompare(b.name)).map((c) => `| ${c.name} | ${c.display} | ${c.body} |`)),
    "\n## Approved or chosen designs (not yet built)\n",
    table("| Trade / design | Branch | Display | Body |\n|---|---|---|---|", claims.filter((c) => c.kind === "approved").map((c) => `| ${c.name} | ${c.branch} | ${c.display} | ${c.body} |`)),
    "\n## Case studies\n\nA case study is a design too: don't reuse these in a new look or another case study.\n",
    table("| Case study | Source | Trade | Display | Body | Other |\n|---|---|---|---|---|---|", claims.filter((c) => c.kind === "case").map((c) => `| ${c.name} | ${c.branch} | ${c.trade} | ${c.display} | ${c.body} | ${c.other.join(", ")} |`)),
  ].join("\n");
  out.set("docs/CLAIMED-FONTS.md", `${NOTE("docs/platform/fonts.md, docs/trades/*/fonts.md and case-studies/*/fonts.md")}\n${fill(read("docs/platform/fonts.md"), "trades", fonts)}\n`);

  const rows = all.map((t) => `| ${t.id} | ${t.name} | ${t.kit ? `\`${t.kit}\`` : "—"} | ${FILES.filter((f) => has(`docs/trades/${t.id}/${f}.md`)).map((f) => `[${f}](${t.id}/${f}.md)`).join(" · ")} |`);
  out.set("docs/trades/README.md", `${NOTE("docs/trades/*/trade.json and the files beside it")}
# Trades

One folder per trade, so trades built in parallel never edit the same lines. Each holds \`trade.json\` (its name and kit)
and the trade's own docs: customer questions (\`questions.md\`), what to build (\`playbook.md\`), its demos and what they
take (\`demo-map.md\`), its speed numbers (\`speed.md\`) and the fonts it claims (\`fonts.md\`). The shared views
(\`docs/SPEED-LOG.md\`, \`docs/CLAIMED-FONTS.md\`, \`docs/DEMO-MAP.md\`, this index) are generated from those files by
\`npm run docs\`, and \`npm run rules\` fails if one is stale. A trade's code lives in its kit, \`src/kits/<kit>/\`.

| Folder | Trade | Kit | Files |
|---|---|---|---|
${rows.join("\n")}
`);

  /** A link list for one kind of trade file, for the hand-written docs that point at each trade. @param {string} kind @param {string} from */
  const links = (kind, from) => all.filter((t) => has(`docs/trades/${t.id}/${kind}.md`)).map((t) => `- ${t.name}: [\`docs/trades/${t.id}/${kind}.md\`](${from}${t.id}/${kind}.md)`).join("\n");
  out.set("docs/CUSTOMER-QUESTIONS.md", between(read("docs/CUSTOMER-QUESTIONS.md"), links("questions", "trades/")));
  out.set("docs/TRADE-PLAYBOOK.md", between(read("docs/TRADE-PLAYBOOK.md"), links("playbook", "trades/")));

  const entries = dirs("case-studies").filter((s) => has(`case-studies/${s}/README.md`)).map((s) => body(read(`case-studies/${s}/README.md`)));
  out.set("case-studies/README.md", `${NOTE("docs/platform/case-studies.md and case-studies/*/README.md")}\n${fill(read("docs/platform/case-studies.md"), "case-studies", entries.join("\n"))}\n`);
  return out;
}

/** Generated files that differ from what's committed. @param {string} root @returns {string[]} */
export function staleDocs(root) {
  return [...generate(root)].filter(([rel, text]) => !existsSync(path.join(root, rel)) || readFileSync(path.join(root, rel), "utf8") !== text).map(([rel]) => rel);
}

/** Stale indexes and doubly claimed font families, as `npm run rules` reports them. @param {string} root @returns {string[]} */
export function docsProblems(root) {
  return [
    ...staleDocs(root).map((f) => `${f}: generated index is out of date; edit the per-trade or per-case-study files, then run npm run docs`),
    ...fontProblems(root),
  ];
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  const root = process.cwd();
  if (process.argv.includes("--check")) {
    const problems = docsProblems(root);
    for (const p of problems) console.error(p);
    process.exit(problems.length ? 1 : 0);
  }
  for (const [rel, text] of generate(root)) writeFileSync(path.join(root, rel), text);
  console.log("Docs indexes written (SPEED-LOG, CLAIMED-FONTS, DEMO-MAP, trades/README, case-studies/README, trade link lists).");
}
